"""Submitted parse-only solver."""


def solve(spec_text, query):
    if query != "parse_only":
        return "same"

    lines = []
    for line in spec_text.splitlines():
        stripped = line.strip()
        if stripped.startswith('#'):
            continue
        lines.append(stripped)

    in_c_block = False
    c_emit = None

    for line in lines:
        if line.startswith('template C('):
            in_c_block = True
        elif in_c_block and line.startswith('template '):
            in_c_block = False
        elif in_c_block and 'emit_source' in line:
            start = line.find('"')
            end = line.rfind('"')
            if start != -1 and end != -1:
                c_emit = line[start+1:end]
                break

    if c_emit:
        start_p = c_emit.find('(')
        end_p = c_emit.rfind(')')
        if start_p != -1 and end_p != -1:
            arg = c_emit[start_p+1:end_p].strip()
            if arg == 'payload':
                return "same"
            else:
                return arg

    return "same"

