"""Submitted parse-only solver."""

import re


_TEMPLATE_CALL_RE = re.compile(
    """
    (?P<name>[A-Za-z_][A-Za-z0-9_-]*)
    \s*
    (
        \(
            (?P<args>.*)
        \)
    )?
    """,
    re.VERBOSE,
)


def solve(spec_text, query):
    if query != "parse_only":
        return None

    rules = parse_rules(spec_text)
    c_rule = find_c_rule(rules)
    if c_rule is None:
        return None

    return payload_operation(c_rule)


def strip_comment(line):
    """Remove a format-only trailing comment from one DSL line."""
    return line.split("#", 1)[0].strip()


def split_header_value(line):
    parts = line.split(":", 1)
    if len(parts) != 2:
        return None, None
    return parts[0].strip().lower(), parts[1].strip()


def parse_template_call(text):
    text = text.strip()
    match = _TEMPLATE_CALL_RE.fullmatch(text)
    if not match:
        return None, None

    args = match.group("args")
    if args is None:
        args = ""
    args = [arg.strip() for arg in split_arguments(args) if arg.strip()]
    return match.group("name"), args


def split_arguments(text):
    """Split top-level comma-separated DSL arguments."""
    args = []
    current = []
    depth = 0
    quote = None
    escaped = False

    for char in text:
        if escaped:
            current.append(char)
            escaped = False
            continue
        if char == "\\":
            current.append(char)
            escaped = True
            continue
        if quote:
            current.append(char)
            if char == quote:
                quote = None
            continue
        if char in "'\"":
            quote = char
            current.append(char)
            continue
        if char in "([{":
            depth += 1
        elif char in ")]}" and depth:
            depth -= 1
        elif char == "," and not depth:
            args.append("".join(current))
            current = []
            continue
        current.append(char)

    if current:
        args.append("".join(current))
    return args


def normalize_label(label):
    label = strip_comment(label).strip()
    if len(label) >= 2 and label[0] == label[-1] and label[0] in "'\"":
        label = label[1:-1]
    return label.strip()


def split_arrow_rule(line):
    for arrow in ("->", "→", "=>"):
        if arrow in line:
            left, right = line.split(arrow, 1)
            return left.strip(), right.strip()
    return None, None


def clean_rule_body(line):
    line = line.strip()
    while line.startswith("-"):
        line = line[1:].strip()
    while line.startswith("*"):
        line = line[1:].strip()
    return line.rstrip(";").strip()


def parse_flat_rules(lines):
    rules = []
    in_rules = False

    for raw_line in lines:
        line = strip_comment(raw_line)
        if not line:
            continue

        key, value = split_header_value(line)
        if key and value == "":
            if key == "rules":
                in_rules = True
                continue
            in_rules = False
            continue
        if key:
            in_rules = False
            continue

        if not in_rules:
            continue

        left, right = split_arrow_rule(clean_rule_body(line))
        if left is None or right is None:
            continue

        source_name, source_args = parse_template_call(left)
        target_name, target_args = parse_template_call(right)
        rules.append(
            {
                "source": (source_name, source_args),
                "target": (target_name, target_args),
            }
        )

    return rules


def parse_rules(spec_text):
    return parse_flat_rules(str(spec_text).splitlines())


def find_c_rule(rules):
    for rule in rules:
        name, _args = rule["source"]
        if name and name.strip().lower() == "c":
            return rule
    return None


def inner_call(text):
    """Return the outermost argument list of a call such as flip(payload)."""
    text = text.strip()
    if not text.endswith(")"):
        return None
    open_index = text.rfind("(")
    if open_index <= 0:
        return None
    return text[open_index + 1 : -1].strip()


def payload_operation(rule):
    """Return the payload operation supplied by the C rule's target."""
    target_name, target_args = rule["target"]
    _ = target_name

    if not target_args:
        return "same"

    payload = target_args[0]
    inner = inner_call(payload)
    if inner is not None:
        payload = inner

    payload = normalize_label(payload)
    if not payload:
        return "same"
    if payload in ("payload", "p", "x", "value", "data", "var", "arg"):
        return "same"
    return payload

